"""
Template cestino (soft-delete con recupero).
"""

TEMPLATE_CESTINO = '\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>{{ _("Cestino") }} — TaskPlanner</title>\n<style>\n:root {\n    --bg-color: #f0f4f8;\n    --card-bg: #ffffff;\n    --text-color: #222;\n    --muted-text: #555;\n    --border-color: #ccc;\n    --accent: #007bff;\n    --danger: #dc3545;\n    --success: #28a745;\n    --warning: #ff9800;\n    --shadow: rgba(0,0,0,0.15);\n}\nbody.dark {\n    --bg-color: #151821;\n    --card-bg: #1f2430;\n    --text-color: #f5f5f5;\n    --muted-text: #aaaaaa;\n    --border-color: #3a3f4b;\n    --accent: #4da3ff;\n    --danger: #ff6b6b;\n    --success: #4cd964;\n    --warning: #ffc94a;\n    --shadow: rgba(0,0,0,0.6);\n}\n* { box-sizing: border-box; margin: 0; padding: 0; }\nbody { font-family: Arial, sans-serif; background: var(--bg-color); color: var(--text-color); padding: 30px; }\n.page-header { display: flex; align-items: center; gap: 16px; margin-bottom: 28px; flex-wrap: wrap; }\n.page-header h1 { font-size: 1.4rem; font-weight: 700; }\n.btn-back {\n    padding: 7px 16px; border-radius: 7px; border: 1px solid var(--border-color);\n    background: transparent; color: var(--text-color); cursor: pointer; font-size: 0.88rem;\n    text-decoration: none; display: inline-flex; align-items: center; gap: 5px; transition: background .15s;\n}\n.btn-back:hover { background: var(--border-color); }\n.badge { background: var(--danger); color: #fff; border-radius: 10px; padding: 2px 8px; font-size: 12px; margin-left: 6px; }\n.toolbar { max-width: 720px; margin: 0 auto 16px auto; display: flex; justify-content: flex-end; }\n.btn-svuota {\n    padding: 8px 18px; border: none; border-radius: 7px; background: var(--danger);\n    color: #fff; cursor: pointer; font-size: 0.9rem; font-weight: 600; transition: opacity .15s;\n}\n.btn-svuota:hover { opacity: .85; }\n.empty { text-align: center; color: var(--muted-text); margin-top: 60px; font-size: 1rem; }\n.auto-delete-notice {\n    max-width: 720px; margin: 0 auto 20px auto;\n    padding: 10px 16px; border-radius: 8px;\n    background: #fff3cd; color: #856404;\n    border: 1px solid #ffc107; font-size: 0.875rem;\n}\nbody.dark .auto-delete-notice { background: #3d3000; color: #ffc94a; border-color: #7a5c0066; }\n.task-list { display: flex; flex-direction: column; gap: 10px; max-width: 720px; margin: 0 auto; }\n.task-card {\n    background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 10px;\n    padding: 14px 18px; display: flex; align-items: center; gap: 14px;\n    box-shadow: 0 1px 4px var(--shadow);\n}\n.task-info { flex: 1; min-width: 0; }\n.task-title { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 0.97rem; }\n.task-meta { font-size: 0.8rem; color: var(--muted-text); margin-top: 3px; }\n.task-days { font-size: 0.8rem; font-weight: 700; white-space: nowrap; }\n.task-days.urgente { color: var(--danger); }\n.task-days.ok { color: var(--muted-text); }\n.btn-action {\n    padding: 7px 14px; border: none; border-radius: 6px; font-size: 0.85rem;\n    cursor: pointer; font-weight: 600; transition: opacity .15s; white-space: nowrap;\n}\n.btn-action:hover { opacity: .85; }\n.btn-restore { background: var(--success); color: #fff; }\n.btn-delete  { background: var(--danger);  color: #fff; }\n@media(max-width:600px) {\n    body { padding: 16px; }\n    .task-card { flex-wrap: wrap; }\n    .btn-action { width: 100%; text-align: center; }\n}\n</style>\n</head>\n<body>\n<script>if(localStorage.getItem(\'taskplanner_theme\')===\'dark\')document.body.classList.add(\'dark\');</script>\n<div class="page-header">\n  <a class="btn-back" href="/">← {{ _("Torna ai task") }}</a>\n  <h1>🗑️ {{ _("Cestino") }}{% if task_eliminati %}<span class="badge">{{ task_eliminati|length }}</span>{% endif %}</h1>\n</div>\n<div class="auto-delete-notice">⏱️ {{ _("I task nel cestino vengono eliminati automaticamente dopo 7 giorni.") }}</div>\n\n{% if not task_eliminati %}\n  <div class="empty">{{ _("Il cestino è vuoto.") }}</div>\n{% else %}\n  <div class="toolbar">\n    <form method="post" action="/cestino/svuota" onsubmit="return confirm(\'{{ _("Eliminare definitivamente tutti i task nel cestino?") }}\')">\n      <button class="btn-svuota" type="submit">{{ _("🗑️ Svuota cestino") }}</button>\n    </form>\n  </div>\n  <div class="task-list">\n    {% for tid, titolo, data_prev, priorita, deleted_at, giorni_rimasti in task_eliminati %}\n    <div class="task-card">\n      <div class="task-info">\n        <div class="task-title">{{ titolo }}</div>\n        <div class="task-meta">{{ data_prev }} &bull; {{ priorita }}</div>\n      </div>\n      <div class="task-days {% if giorni_rimasti <= 2 %}urgente{% else %}ok{% endif %}">\n        {% if giorni_rimasti == 0 %}{{ _("Eliminato domani") }}\n        {% elif giorni_rimasti == 1 %}{{ _("1 giorno") }}\n        {% else %}{{ ngettext("%(num)d giorno", "%(num)d giorni", giorni_rimasti) }}\n        {% endif %}\n      </div>\n      <form method="post" action="/cestino/restore/{{ tid }}" style="display:inline">\n        <button class="btn-action btn-restore" type="submit">{{ _("↩ Ripristina") }}</button>\n      </form>\n      <form method="post" action="/cestino/elimina/{{ tid }}" onsubmit="return confirm(\'{{ _("Eliminare definitivamente questo task?") }}\')" style="display:inline">\n        <button class="btn-action btn-delete" type="submit">{{ _("✕ Elimina") }}</button>\n      </form>\n    </div>\n    {% endfor %}\n  </div>\n{% endif %}\n</body>\n</html>\n'
